"""Total values by key and answer queries.

Usage: python main.py <input-file>

The input file has two sections separated by one empty line. The first holds
"<key> <value>" records; the second holds one key per line to answer. Keys are
compared as raw bytes, so the program never needs to decode them.
"""

import sys

INT64_MIN = -(2**63)
INT64_MAX = 2**63 - 1


def parse(data: bytes):
    """Split the file into (records, queries), each a list of byte lines."""
    lines = data.split(b"\n")
    if lines and lines[-1] == b"":
        lines.pop()

    records = []
    queries = []
    in_queries = False
    for raw in lines:
        line = raw[:-1] if raw.endswith(b"\r") else raw
        if not in_queries:
            if line == b"":
                in_queries = True
            else:
                records.append(line)
        elif line != b"":
            queries.append(line)
    return records, queries


def totals(records):
    """Map each key to (total, overflowed), summing in record order."""
    result = {}
    for line in records:
        parts = line.rsplit(None, 1)
        if len(parts) != 2:
            continue
        key, value_bytes = parts
        value = int(value_bytes)

        total, overflowed = result.get(key, (0, False))
        if not overflowed:
            total += value
            if total < INT64_MIN or total > INT64_MAX:
                overflowed = True
        result[key] = (total, overflowed)
    return result


def main(argv):
    if len(argv) != 2:
        print("usage: main.py <input-file>", file=sys.stderr)
        return 2

    with open(argv[1], "rb") as f:
        data = f.read()

    records, queries = parse(data)
    table = totals(records)

    out = []
    for key in queries:
        if key not in table:
            out.append(key + b"=absent\n")
            continue
        total, overflowed = table[key]
        if overflowed:
            out.append(key + b"=overflow\n")
        else:
            out.append(key + b"=" + str(total).encode("ascii") + b"\n")

    if out:
        sys.stdout.buffer.write(b"".join(out))
        sys.stdout.buffer.flush()
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

